solution.solution.cpp:
#include <functional>
#include <utility>

class Finally
{
public:
    explicit Finally(std::function<void()> action) : m_action{ std::move(action) } {}
    ~Finally() { if (m_action) m_action(); }

    Finally(const Finally&) = delete;
    Finally& operator=(const Finally&) = delete;

    void dismiss() { m_action = nullptr; }

private:
    std::function<void()> m_action{};
};

unitTests:
static_assert(!std::is_copy_constructible_v<Finally>, "Finally must not be copyable");

TEST("runs at the end of the scope, not before") { std::string log; { Finally f{ [&] { log += "end"; } }; log += "body,"; } CHECK_EQ(log, "body,end"); }
TEST("dismiss cancels it") { int runs{ 0 }; { Finally f{ [&] { ++runs; } }; f.dismiss(); } CHECK_EQ(runs, 0); }
TEST("several run in reverse order") { std::string log; { Finally a{ [&] { log += 'a'; } }; Finally b{ [&] { log += 'b'; } }; } CHECK_EQ(log, "ba"); }

